/**
 * The API client announces the interface language on every request and words its own
 * errors in it; a 401 from the language switch must not end the session.
 *
 * Value: protects=Accept-Language follows <html lang>; stayOnUnauthorized keeps the token and
 * the page; client errors are in the interface language; fails_when=the header is dropped from
 * buildHeaders, or the 401 branch ignores stayOnUnauthorized; why_new=no test covered
 * api-client.ts; seam=none
 * Generated by /ship test coverage audit (pass 1).
 */
import { api, type ApiError } from "./api-client";

const fetchMock = jest.fn();

function jsonResponse(status: number, body: unknown) {
  return {
    status,
    statusText: "",
    headers: { get: () => "application/json" },
    json: async () => body,
  };
}

function sentHeaders(): Record<string, string> {
  return fetchMock.mock.calls[0][1].headers;
}

beforeEach(() => {
  fetchMock.mockReset();
  global.fetch = fetchMock as unknown as typeof fetch;
  localStorage.clear();
  document.documentElement.lang = "en";
});

describe("api client", () => {
  it("announces the interface language, and follows a switch", async () => {
    fetchMock.mockResolvedValue(jsonResponse(200, { data: { ok: true } }));

    document.documentElement.lang = "fr";
    await api.post("/auth/login", { email: "a@b.co", password: "x" });
    expect(sentHeaders()["Accept-Language"]).toBe("fr");

    fetchMock.mockClear();
    document.documentElement.lang = "en";
    await api.get("/dashboard");
    expect(sentHeaders()["Accept-Language"]).toBe("en");
  });

  it("keeps the session and the page on a 401 when asked to stay", async () => {
    localStorage.setItem("token", "t0k3n");
    localStorage.setItem("user", "{}");
    document.documentElement.lang = "fr";
    fetchMock.mockResolvedValue(jsonResponse(401, { error: { code: "UNAUTHORIZED", message: "x" } }));

    const err = (await api.put("/auth/me", { locale: "fr" }, { stayOnUnauthorized: true }).catch((e: unknown) => e)) as ApiError;

    expect(err.code).toBe("UNAUTHORIZED");
    expect(err.message).toBe("Session expirée");
    expect(localStorage.getItem("token")).toBe("t0k3n");
    expect(localStorage.getItem("user")).toBe("{}");
  });

  it("still ends the session on a 401 by default", async () => {
    localStorage.setItem("token", "t0k3n");
    fetchMock.mockResolvedValue(jsonResponse(401, {}));

    await expect(api.get("/dashboard")).rejects.toMatchObject({ code: "UNAUTHORIZED", message: "Session expired" });
    expect(localStorage.getItem("token")).toBeNull();
  });

  // Regression: ISSUE-005 — a wrong password reloaded /login and the server's message was lost
  // Found by /ship QA on 2026-10-01
  // Report: .gstack/qa-reports/ship-20261001/report.md
  it.each([
    ["no session on the device", null],
    ["an old session still stored", "old-t0k3n"],
  ])("shows a refused sign-in's own message with %s, without ending a session", async (_case, token) => {
    if (token) localStorage.setItem("token", token);
    localStorage.setItem("user", "{}");
    document.documentElement.lang = "fr";
    fetchMock.mockResolvedValue(
      jsonResponse(401, { error: { code: "UNAUTHORIZED", message: "Courriel ou mot de passe incorrect.", details: [] } })
    );

    await expect(api.post("/auth/login", { email: "a@b.co", password: "wrongpass" })).rejects.toMatchObject({
      code: "UNAUTHORIZED",
      message: "Courriel ou mot de passe incorrect.",
    });
    // clearAuthAndRedirect() would have removed both
    expect(localStorage.getItem("token")).toBe(token);
    expect(localStorage.getItem("user")).toBe("{}");
  });

  // A tab whose token was removed elsewhere (sign-out in another tab) still sends its requests,
  // with no Authorization header: the 401 must send it to sign-in, not show an inline error
  it("ends the session on a 401 from any other call, even one sent without a token", async () => {
    localStorage.setItem("user", "{}");
    fetchMock.mockResolvedValue(jsonResponse(401, { error: { code: "UNAUTHORIZED", message: "Authentication required.", details: [] } }));

    await expect(api.get("/identity/status")).rejects.toMatchObject({ code: "UNAUTHORIZED", message: "Session expired" });
    expect(localStorage.getItem("user")).toBeNull();
  });

  it("words an unexpected response in the interface language", async () => {
    document.documentElement.lang = "fr";
    fetchMock.mockResolvedValue({ status: 502, statusText: "Bad Gateway", headers: { get: () => "text/html" } });

    const err = (await api.get("/dashboard").catch((e: unknown) => e)) as ApiError;

    expect(err.code).toBe("NON_JSON_RESPONSE");
    expect(err.message).toBe("Le serveur a renvoyé une réponse inattendue (502 Bad Gateway)");
  });
});
